UPDATE content SET overview_uk = v.overview_uk, has_uk_translation = true FROM (VALUES
  (5910, 'Агент з боротьби з тероризмом Джек Бауер протистоїть лиходіям по всьому світу — один день за раз. Кожен епізод розгортається в реальному часі, і кожен сезон охоплює одну добу з життя Бауера.'),
  (5828, 'Зазирніть у напружені будні поліцейських, парамедиків і пожежників, які опиняються в найстрашніших, найшокуючіших і найнапруженіших ситуаціях. Ці рятувальники мають балансувати між порятунком найбільш вразливих людей і вирішенням проблем у власному житті.'),
  (6723, 'Заступниця начальника поліції Бренда Лі Джонсон переводиться з Атланти до Лос-Анджелеса, щоб очолити спецпідрозділ поліції, який розслідує резонансні справи про вбивства. Ексцентричний характер і жорсткий підхід Джонсон часто дратують колег, але її репутація одного з найкращих слідчих у світі зрештою підкорює навіть найзатятіших критиків.'),
  (5746, 'Зникнення дитини штовхає чотири родини на гарячкові пошуки відповідей — і розкриває неймовірну таємницю, що охоплює три покоління.'),
  (6313, 'Він — улюблений герой бойовиків для всіх... але герой особливий. Ангус МакГайвер — таємний агент, чия найсмертоносніша зброя — його кмітливість. Озброєний лише рюкзаком із повсякденними речами, зібраними по дорозі, він імпровізує, щоб вибратися з будь-якої пастки. Зробити бомбу з жуйки? Полагодити гальма авто на ходу — прямо зсередини? Виготовити сльозогінний газ із газованої води? Для МакГайвера це — звичайний день пригод. Він частково бойскаут, частково геній. І цілком герой.'),
  (5889, 'В епоху, сповнену небезпеки, обману та інтриг, Кассіан Андор відкриє для себе, яку роль він може відіграти в боротьбі проти тиранічної Галактичної Імперії. Він вирушає шляхом, якому судилося перетворити його на героя повстання.'),
  (5973, 'Давним-давно богині Афіні служили воїни, звані Святими, які спрямовували силу Космосу всередині себе. Тепер юнак на ім''я Сейя пройшов навчання, щоб стати Святим, здобувши містичний Обладунок Пегаса. До нього приєднуються інші Святі з власними Обладунками, щоб битися за Афіну.'),
  (6665, 'Єдина жінка-детектив у відділі вбивств Філадельфії знаходить своє покликання, коли їй доручають нерозкриті справи. Детектив Ліллі Раш поєднує природну інтуїцію із сучасними технологіями, щоб домогтися справедливості для всіх жертв, яким вона може допомогти.'),
  (6238, 'Натхненний однойменними коміксами, кожен епізод цього анімаційного серіалу-антології ставить під сумнів, переосмислює та перевертає з ніг на голову знакові моменти Кінематографічного Всесвіту Marvel.'),
  (5838, 'Лім Джу-кьон — старшокласниця, яка з дитинства має комплекси через свою зовнішність. Щоб приховати обличчя без макіяжу, Джу-кьон завжди фарбується. Її майстерний макіяж робить її гарною, і вона ретельно приховує своє справжнє обличчя від оточуючих. У її житті з''являються двоє хлопців — Лі Су-хо та Хан Со-джун.'),
  (6623, 'Оперативна група з розшуку безперервно вистежує та затримує сумнозвісних злочинців зі списку найбільш розшукуваних ФБР. Досвідчені агенти керують висококваліфікованою командою, яка працює як мобільний підрозділ під прикриттям, завжди перебуваючи в полі та переслідуючи тих, хто найвідчайдушніше намагається уникнути правосуддя.'),
  (5580, 'Група молодих людей проводить підлітковий вік у школі Elite Way, де вони пізнають кохання, життя та живуть своєю пристрастю до музики.'),
  (5732, 'Після викрадення Тессеракта під час подій «Месників: Завершення», альтернативна версія Локі потрапляє до загадкового Управління Часових Варіацій — бюрократичної організації, що існує поза часом і простором та стежить за часовою лінією. Локі ставлять перед вибором: бути стертим з існування як «часовий варіант» або допомогти виправити часову лінію та зупинити більшу загрозу.'),
  (155, 'На своє шістнадцятиріччя Сабріна Спеллман дізнається, що має магічні здібності. Вона живе зі своїми 600-річними тітками Гільдою та Зельдою, а також з котом-говоруном Салемом у вигаданому містечку Вестбридж, штат Массачусетс.'),
  (7039, 'Американський комедійний серіал з Біллом Косбі у головній ролі, що виходив вісім сезонів на каналі NBC з 20 вересня 1984 року по 30 квітня 1992 року. Серіал розповідає про родину Хакстейблів — афроамериканську сім''ю з верхнього середнього класу, яка мешкає у Брукліні, Нью-Йорк.')
) AS v(id, overview_uk) WHERE content.id = v.id;
